  "content": "1|import React from 'react';
2|import { Save, X } from 'lucide-react';
3|import { FeatureToggleField, UiInput, UiSelect } from '../../../../shared/ui';
4|import { AI_WEB_SEARCH_PROVIDER_OPTIONS } from '../../../../shared/api/contracts/ai/constants';
5|import type { AiWebSearchProvider } from '../../../../shared/api/contracts/ai/types';
6|import { AppButton } from '../../../../shared/ui/AppButton';
7|import { CreateEditModalShell } from '../../../../shared/ui/CreateEditModalShell';
8|import { SETTINGS_FORM_GROUP_BODY_STACK_CLASS, SETTINGS_FORM_TWO_COL_GRID_GAP_CLASS } from '../form/SettingsFormPrimitives';
9|
10|export type McpWebSearchDraft = {
11|  provider: AiWebSearchProvider;
12|  apiKey: string;
13|  maxResults: number;
14|};
15|
16|export type McpWebSearchModalProps = {
17|  open: boolean;
18|  draft: McpWebSearchDraft;
19|  formError: string | null;
20|  hasStoredApiKey: boolean;
21|  isSaving: boolean;
22|  onClose: () => void;
23|  onSubmit: () => void;
24|  onDraftChange: (next: McpWebSearchDraft) => void;
25|};
26|
27|const fieldLabelClass = 'block text-sm font-semibold text-slate-700 ps-[4px]';
28|
29|export const McpWebSearchModal: React.FC<McpWebSearchModalProps> = ({
30|  open,
31|  draft,
32|  formError,
33|  hasStoredApiKey,
34|  isSaving,
35|  onClose,
36|  onSubmit,
37|  onDraftChange,
38|}) => {
39|  if (!open) return null;
40|
41|  return (
42|    <CreateEditModalShell
43|      size="3xl"
44|      title="Web / Search — appendo-web"
45|      onClose={onClose}
46|      footer={(
47|        <>
48|          <AppButton intent="cancel" onClick={onClose} disabled={isSaving}>
49|            <X className="h-3.5 w-3.5" />
50|            Cancel
51|          </AppButton>
52|          <AppButton intent="primary" onClick={onSubmit} disabled={isSaving}>
53|            <Save className="h-3.5 w-3.5" />
54|            {isSaving ? 'Saving...' : 'Save'}
55|          </AppButton>
56|        </>
57|      )}
58|    >
59|      <div className={SETTINGS_FORM_GROUP_BODY_STACK_CLASS}>
60|        <p className="text-xs text-slate-500">
61|          Configure the search provider for the <code className="text-[11px]">web_search</code> agent tool.
62|          <code className="text-[11px]">fetch_url</code> and <code className="text-[11px]">screenshot_url</code> use SSRF protection and do not require a provider.
63|        </p>
64|
65|        {formError ? <p className="text-xs font-semibold text-rose-600">{formError}</p> : null}
66|
67|        <section className={SETTINGS_FORM_TWO_COL_GRID_GAP_CLASS}>
68|          <div className="flex flex-col gap-[2px]">
69|            <label className={fieldLabelClass}>Provider</label>
70|            <UiSelect
71|              size="sm"
72|              value={draft.provider}
73|              onChange={(event) => onDraftChange({
74|                ...draft,
75|                provider: event.target.value as AiWebSearchProvider,
76|              })}
77|            >
78|              {AI_WEB_SEARCH_PROVIDER_OPTIONS.map((option) => (
79|                <option key={option.value} value={option.value}>{option.label}</option>
80|              ))}
81|            </UiSelect>
82|          </div>
83|
84|          <div className="flex flex-col gap-[2px]">
85|            <label className={fieldLabelClass}>Max results</label>
86|            <UiInput
87|              size="sm"
88|              type="number"
89|              value={draft.maxResults}
90|              onChange={(event) => onDraftChange({
91|                ...draft,
92|                maxResults: Number(event.target.value) || 1,
93|              })}
94|              disabled={draft.provider === 'disabled'}
95|            />
96|          </div>
97|
98|          <div className="flex flex-col gap-[2px] md:col-span-2">
99|            <label className={fieldLabelClass}>API key</label>
100|            <UiInput
101|              size="sm"
102|              type="password"
103|              value={draft.apiKey}
104|              onChange={(event) => onDraftChange({ ...draft, apiKey: event.target.value })}
105|              placeholder={hasStoredApiKey ? 'Stored key — leave blank to keep' : 'Provider API key'}
106|              disabled={draft.provider === 'disabled'}
107|            />
108|          </div>
109|        </section>
110|
111|        <FeatureToggleField
112|          checked={draft.provider !== 'disabled'}
113|          onChange={(enabled) => onDraftChange({
114|            ...draft,
115|            provider: enabled ? (draft.provider === 'disabled' ? 'brave' : draft.provider) : 'disabled',
116|          })}
117|          title="Enabled"
118|          description="When off, web search is unavailable in Agent capabilities."
119|        />
120|      </div>
121|    </CreateEditModalShell>
122|  );
123|};
124|"
}
